    "@typescript-eslint",
    "prettier",
    "promise"
  ],
  "rules": {
    "jsx-no-lambda": "off",
    "linebreak-style": ["error", "unix"],
    "max-len": [
      "error",
      {
        "code": 100,
        "ignoreComments": true
      }
